/**
 * Campos aceitos em {@code PUT /api/user}, todos opcionais.
 *
 * <p>Não é um record porque precisa distinguir campo ausente de campo enviado como {@code null}:
 * {@code "bio": null} apaga a bio, enquanto omitir {@code bio} a mantém. Para {@code email},
 * {@code username} e {@code password}, {@code null} equivale a não alterar.
 */
public final class UpdateUserFields {

    @Email(message = INVALID)
    @Pattern(regexp = NOT_BLANK_PATTERN, message = BLANK)
    @Size(max = 254, message = TOO_LONG)
    private String email;

    @Pattern(regexp = NOT_BLANK_PATTERN, message = BLANK)
    @Size(max = 64, message = TOO_LONG)
    private String username;

    @Pattern(regexp = NOT_BLANK_PATTERN, message = BLANK)
    private String password;

    private String bio;
    private boolean bioPresent;

    private String image;
    private boolean imagePresent;

    @JsonProperty("email")
    void setEmail(String email) {
        this.email = email;
    }

    @JsonProperty("username")
    void setUsername(String username) {
        this.username = username;
    }

    @JsonProperty("password")
    void setPassword(String password) {
        this.password = password;
    }

    @JsonProperty("bio")
    void setBio(String bio) {
        this.bio = bio;
        this.bioPresent = true;
    }

    @JsonProperty("image")
    void setImage(String image) {
        this.image = image;
        this.imagePresent = true;
    }

    String getEmail() {
        return email;
    }

    String getUsername() {
        return username;
    }

    String getPassword() {
        return password;
    }

    String getBio() {
        return bio;
    }

    boolean isBioPresent() {
        return bioPresent;
    }

    String getImage() {
        return image;
    }

    boolean isImagePresent() {
        return imagePresent;
    }
}

