                .andExpect(jsonPath("$.user.image").value("https://img.example.test/a.png"))
                .andExpect(jsonPath("$.user.token").value(token));

        mockMvc.perform(json(put("/api/user"), token, """
                        {"user":{"image":null,"password":"nova-senha"}}
                        """))
